INSERT INTO measurements_normalized (session_id, participant_id, condition, metric, value, unit, recorded_at, status, source_notes)
SELECT session_id, participant_id, condition, 'cognitive_score', cognitive_score, 'points', recorded_at, status, notes FROM measurements;

INSERT INTO measurements_normalized (session_id, participant_id, condition, metric, value, unit, recorded_at, status, source_notes)
SELECT session_id, participant_id, condition, 'reaction_time', reaction_ms, 'ms', recorded_at, status, notes FROM measurements;

SELECT COUNT(*) AS rows_normalized FROM measurements_normalized;

